'@

if ($OnWindows -and -not $FilesOnly -and $Qt) {
  Step 'Desktop shell (WebView2): not built with -Qt (run this file again without -Qt to switch back)'
  if (-not $NoLaunch) {
    Say '  Opening the Qt window; it finds or starts the Pilcrow server itself.'
    Start-Process -FilePath $QtPythonw -ArgumentList (@('-m', 'pilcrow_qt_launch', '--node', ('"' + $NodePath + '"')) + $QtExtra) -WorkingDirectory $Dir | Out-Null
  }
} elseif ($OnWindows -and -not $FilesOnly) {
  Step 'Desktop shell (WebView2)'
  if (-not (Test-Path $HostDir)) { New-Item -ItemType Directory -Force $HostDir | Out-Null }
  $hostScript = Join-Path $HostDir 'pilcrow-app.ps1'
  $hostBytes = [Convert]::FromBase64String(($HostPayload -replace '\s', ''))
  $hostDigest = ([BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($hostBytes)) -replace '-', '').ToLowerInvariant()
  if ($hostDigest -ne '8e1a096875e766253b2aeed73f26f6b875412cef16f8fdec745656822c022e48') { Die "The embedded shell script is incomplete or was altered (checksum mismatch). Download or copy the installer again." }
  [IO.File]::WriteAllBytes($hostScript, $hostBytes)
  Ok "Shell script: $hostScript (verified)"
  # Windows PowerShell 5.1 (WinForms + WebView2 need it). The file was written a moment ago by this
  # installer, so it carries no Internet mark; Bypass covers the Restricted default of client Windows.
  $ps51 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
  $hostArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA', '-File', ('"' + $hostScript + '"'), '-Install', '-Dir', ('"' + $Dir + '"'))
  foreach ($sw in @('NoDesktop', 'NoLaunch', 'KeepServer', 'NativeTitleBar', 'DevTools', 'SkipSignatureCheck')) {
    if ((Get-Variable $sw -ValueOnly).IsPresent) { $hostArgs += "-$sw" }
  }
  foreach ($opt in @('Node', 'Python', 'WebView2Package', 'NuGetSource', 'WebView2Version', 'WebView2Runtime')) {
    $v = Get-Variable $opt -ValueOnly
    if ($v) { $hostArgs += "-$opt"; $hostArgs += ('"' + $v + '"') }
  }
  Say '  Preparing the WebView2 SDK (pip) and compiling the shell; the Pilcrow window opens when it is ready.'
  $hp = Start-Process -FilePath $ps51 -ArgumentList $hostArgs -Wait -PassThru -NoNewWindow
  if ($hp.ExitCode -ne 0) {
    Warn "The desktop shell did not finish (exit $($hp.ExitCode)). Pilcrow itself is installed; fix the message above and run this file again, or start it with: pilcrow"
  } else {
    Ok 'Desktop shell ready'
  }
}

Write-Host ''
Write-Host "Pilcrow $Version installed" -ForegroundColor Green
if ($OnWindows) {
  if ($Qt) { Say "  Start: Pilcrow in the Start menu or on the desktop (the Qt window), or run  pilcrow-qt  in a terminal" }
  else { Say "  Start: Pilcrow in the Start menu or on the desktop, or run  pilcrow  in a terminal" }
  Say "  Health check: pilcrow --doctor    Remove: run this file again with -Uninstall"
}
Say ("  Docs: " + (Join-Path $Dir 'README.md'))